<template><div class="app-container"><el-tabs v-model="statusTab" @tab-change="search"><el-tab-pane label="全部标签" name="all"/><el-tab-pane v-for="s in statusOptions" :key="s.value" :label="s.label" :name="s.value"/></el-tabs><el-form inline @submit.prevent="search"><el-form-item label="名称前缀"><el-input v-model="q.name" clearable maxlength="40" @keyup.enter="search"/></el-form-item><el-button type="primary" @click="search">搜索</el-button><el-button @click="q.name='';q.status='';search()">重置</el-button><el-button v-hasPermi="['cms:tag:add']" @click="edit()">新增标签</el-button></el-form><el-alert title="标签用于给文章、产品加多个主题标记，如“Go”“教程”，支持前台筛选。停用后不能新选；历史发布版保留当时的标签名称。" :closable="false"/><el-table :data="rows" v-loading="loading"><el-table-column prop="tagId" label="编号" width="90"/><el-table-column prop="name" label="标签"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.status==='0'?'success':'info'">{{statusOptions.find(o=>o.value===s.row.status)?.label||s.row.status}}</el-tag></template></el-table-column><el-table-column prop="updateTime" label="修改时间" width="170"/><el-table-column label="操作" width="100"><template #default="s"><el-button v-hasPermi="['cms:tag:edit']" link type="primary" @click="edit(s.row)">修改</el-button></template></el-table-column></el-table><pagination v-show="total" :total="total" v-model:page="q.pageNum" v-model:limit="q.pageSize" @pagination="load"/><el-dialog v-model="opened" :title="form.tagId?'修改标签':'新增标签'" width="450px" append-to-body :close-on-click-modal="false"><el-form label-width="70px" @submit.prevent><el-form-item label="名称"><el-input v-model="form.name" maxlength="40"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio v-for="s in statusOptions" :key="s.value" :value="s.value">{{s.label}}</el-radio></el-radio-group></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" maxlength="500" type="textarea"/></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="opened=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>
import { statusChoices } from '@/utils/cmsOptions.mjs'
import {ref,computed,reactive,onMounted,onBeforeUnmount,onDeactivated} from 'vue'
import {ElMessage} from 'element-plus'
import request from '@/utils/request'
const q=reactive({pageNum:1,pageSize:10,name:'',status:''}),rows=ref([]),total=ref(0),loading=ref(false),busy=ref(false),opened=ref(false),form=ref({});let epoch=0
const statusTab=computed({get:()=>q.status||'all',set:v=>q.status=v==='all'?'':v})
async function load(){const ticket=++epoch;loading.value=true;try{const r=await request({url:'/cms/tag/list',params:{...q}});if(ticket===epoch){rows.value=r.rows;total.value=r.total}}finally{if(ticket===epoch)loading.value=false}}
function search(){q.pageNum=1;load()}
function edit(row){form.value=row?{...row}:{tagId:0,version:0,name:'',status:'0',remark:''};opened.value=true}
async function save(){if(busy.value||!form.value.name.trim())return;busy.value=true;try{await request({url:'/cms/tag',method:form.value.tagId?'put':'post',data:form.value});opened.value=false;ElMessage.success('标签已保存');await load()}finally{busy.value=false}}
function cleanup(){++epoch;opened.value=false}onMounted(load);onBeforeUnmount(cleanup);onDeactivated(cleanup)
const {sys_normal_disable}=getCurrentInstance().proxy.useDict('sys_normal_disable')
const statusOptions=computed(()=>statusChoices(sys_normal_disable.value))
</script>